s=s[:start]+'''/** A cache younger than this is used as-is rather than asking the endpoint again. */
export const CACHE_SKIP_MS = 60 * 1000

/** How old the status line's cache may be and still stand in for a refused endpoint. */
export const CACHE_FALLBACK_MS = 15 * 60 * 1000

/** Last `/usage` spawn per cache file, so a failing one is retried once per lever TTL, not per press. */
const leversAttempts = new Map<string, number>()

/**
 * Take a live reading and fold it into the shared cache.
 *
 * `/usage` reads the same rate-limited endpoint, and when that endpoint
 * refuses, the CLI hands `/usage` to the model as a prompt: a paid turn whose
 * prose parses to nothing. So a refused endpoint never leads to a spawn; the
 * status line's cache stands in while it is fresh.
 * @param timeoutMs - hard cap on the CLI call.
 * @param path - cache file; defaults to the status line's own.
 * @param configDir - config directory identifying the account to read; defaults to the desktop account's.
 * @returns the reading, or undefined when nothing fresh enough could be read.
 */
export async function refresh(timeoutMs?: number, path?: string, configDir?: string): Promise<QuotaReading | undefined> {
  const cached = readCache(path)
  const api = await readUsageApi(configDir)
  if (api === undefined) {
    const fresh = cached !== undefined && Date.now() - (cached.capturedAt ?? 0) < CACHE_FALLBACK_MS
    return fresh ? cached : undefined
  }
  // A `/usage` turn is only worth its cost for the request counts and spend
  // levers, which the endpoint does not carry.
  const key = path ?? defaultCachePath()
  const leversFresh = Date.now() - Math.max(cached?.leversAt ?? 0, leversAttempts.get(key) ?? 0) < LEVERS_TTL_MS
  let levers: QuotaReading = {}
  if (!leversFresh) {
    leversAttempts.set(key, Date.now())
    const text = parseUsage(await readUsageText(timeoutMs, configDir))
    if (isUsable(text) && text.requests24h !== undefined) levers = { ...stripQuota(text), leversAt: Date.now() }
  }
  // The endpoint's percentages win: the text is a snapshot of when the CLI
  // started, which can be a minute old by the time it exits.
  const reading: QuotaReading = { ...stripQuota(cached), ...levers, ...api }
  writeCache(reading, path)
  return reading
}
'''
