/**
 * A stand-in for a signed-in chat.deepseek.com: a textarea whose React-style
 * listener only sees text that arrived through an `input` event, Enter to send,
 * reasoning streamed into its own panel first, then the answer in pieces.
 */
function mountDeepSeek(answerParts: readonly string[], options: { refuseSend?: boolean } = {}): { sent: string[] } {
  document.body.innerHTML = '<div id="chat"><div class="ds-markdown">an earlier answer</div></div><textarea></textarea>'
  const chat = document.getElementById('chat')!
  const box = document.querySelector('textarea')!
  const sent: string[] = []
  let seen = ''
  box.addEventListener('input', () => { seen = box.value })
  box.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' || options.refuseSend === true) return
    sent.push(seen)
    box.value = ''
    setTimeout(() => {
      chat.insertAdjacentHTML('beforeend', '<div class="ds-think-content"><div class="ds-markdown">thinking...</div></div>')
    }, 50)
    const answer = document.createElement('div')
    answer.className = 'ds-markdown'
    answerParts.forEach((part, i) => {
      setTimeout(() => {
        if (i === 0) chat.append(answer)
        answer.insertAdjacentHTML('beforeend', part)
      }, 400 + i * 300)
    })
  })
